    // Helper: check if a body-part row has a given checkbox status (normal or abnormal)
    // Extracts the row section containing rowLabel, then checks if the span before checkboxLabel has "on"
    private static bool BodyPartCheckboxIsOn(string html, string rowLabel, string checkboxLabel)
    {
        // Find the row excerpt containing rowLabel
        var idx = html.IndexOf(rowLabel, StringComparison.Ordinal);
        if (idx < 0) return false;
        var rowExcerpt = html.Substring(idx, Math.Min(400, html.Length - idx));

        // Find the span immediately before checkboxLabel text
        // Pattern: <span class="cb ...">(empty)</span>checkboxLabel
        var pattern = @"<span class=""cb ([^""]*)""></span>" + Regex.Escape(checkboxLabel);
        var m = Regex.Match(rowExcerpt, pattern);
        if (!m.Success) return false;
        return m.Groups[1].Value.Contains("on");
    }

