        var data = SampleData(rec => rec.PhysicalExamination.Fur = "異常,打結");
        var renderer = new ContractTemplateRenderer(_templatePath, _fontPath);
        var html = renderer.Render(data);

        var idx = html.IndexOf("6.皮毛", StringComparison.Ordinal);
        var rowExcerpt = html.Substring(idx, Math.Min(400, html.Length - idx));

        // 異常勾 / 打結勾 / 正常不勾
        var patterns = Regex.Matches(rowExcerpt, @"<span class=""cb ([^""]*)""></span>([^<]+)");
        var checkboxMap = patterns.ToDictionary(m => m.Groups[2].Value.Trim(), m => m.Groups[1].Value.Contains("on"));
        checkboxMap.Should().ContainKey("異常").WhoseValue.Should().BeTrue("皮毛含異常 → 異常應勾");
        checkboxMap.Should().ContainKey("打結").WhoseValue.Should().BeTrue("皮毛含打結 → 打結應勾");
        if (checkboxMap.ContainsKey("正常"))
            checkboxMap["正常"].Should().BeFalse("皮毛含異常+打結 → 正常不勾");
    }

