        var noteColumns = new[] { "phys_eyes_note", "phys_ears_note", "phys_teeth_note", "phys_limbs_note", "phys_skin_note", "phys_fur_note" };

        // 查 pets table
        using (var cmd = conn.CreateCommand())
        {
            cmd.CommandText = "PRAGMA table_info('pets')";
            using var reader = await cmd.ExecuteReaderAsync();
            var cols = new List<string>();
            while (await reader.ReadAsync()) cols.Add(reader.GetString(1));
