        };
        var appt = new Appointment
        {
            AppointmentId = "appt_q9", OwnerId = owner.OwnerId, PetId = pet.PetId,
            Date = new DateOnly(2026, 5, 16), Time = new TimeOnly(10, 0)
        };
        db.Owners.Add(owner);
        db.Pets.Add(pet);
        db.Appointments.Add(appt);
        await db.SaveChangesAsync();

        // When 建立 GroomingRecord，設定 Eyes="異常"、EyesNote="結膜發紅"
        var groomingRecord = new GroomingRecord
        {
            GroomingRecordId = "rec_q9", AppointmentId = appt.AppointmentId,
            ServiceDate = appt.Date, ServiceTime = appt.Time,
            PhysicalExamination = new PhysicalExamination { Eyes = "異常", EyesNote = "結膜發紅" },
        };
        db.GroomingRecords.Add(groomingRecord);
        await db.SaveChangesAsync();

        // Then GroomingRecord 寫入後其 PhysicalExamination 應為 "異常"
        var loadedRec = await db.GroomingRecords.AsNoTracking().FirstAsync(r => r.GroomingRecordId == "rec_q9");
        loadedRec.PhysicalExamination.Eyes.Should().Be("異常");
        loadedRec.PhysicalExamination.EyesNote.Should().Be("結膜發紅");

        // And Pet 的 PhysicalExamination 應仍為 "正常"（未被 GroomingRecord 改寫）
        var loadedPet = await db.Pets.AsNoTracking().FirstAsync(p => p.PetId == "pet_q9");
        loadedPet.PhysicalExamination.Eyes.Should().Be("正常", "GroomingRecord 儲存不應回寫 Pet.PhysicalExamination");
        loadedPet.PhysicalExamination.EyesNote.Should().BeNull("Pet.EyesNote 應仍為 null");

        await connection.CloseAsync();
        connection.Dispose();
    }

    [Fact(DisplayName = "R6/Q9 / 新建 GroomingRecord 之 PhysicalExamination 預設值來自 Pet")]
    public async Task New_grooming_record_defaults_from_pet_physical_examination()
    {
        // 驗證 GroomingRecord 的 PhysicalExamination 初始值來自 Pet
        // 這是 ViewModel 層的行為，在測試中用 entity 直接驗證預設值邏輯

        var connection = new SqliteConnection("DataSource=:memory:");
        connection.Open();
        var options = new DbContextOptionsBuilder<PetSalonDbContext>()
            .UseSqlite(connection)
            .Options;
        await using var db = new PetSalonDbContext(options);
        db.Database.EnsureCreated();

        // Given Pet.PhysicalExamination.Eyes="正常"
        var owner = new Owner { OwnerId = "owner_q9b", Name = "王小明", NationalId = "A123456789", Phone = "0912345678", Address = "桃園市" };
        var pet = new Pet
        {
            PetId = "pet_q9b", OwnerId = owner.OwnerId, Name = "小白", Species = "犬", Breed = "柴犬", Gender = "公", Age = "3 歲",
            Personality = new List<string> { "親人" },
            PhysicalExamination = new PhysicalExamination { Eyes = "正常" },
        };
        db.Owners.Add(owner);
        db.Pets.Add(pet);
        await db.SaveChangesAsync();

        // When 透過 ViewModel 端建立新 GroomingRecord（模擬：直接複製 Pet 的 PhysicalExamination）
        var newRec = new GroomingRecord
        {
            GroomingRecordId = "rec_q9b",
            PhysicalExamination = new PhysicalExamination
            {
                Eyes = pet.PhysicalExamination.Eyes,
                Ears = pet.PhysicalExamination.Ears,
                Teeth = pet.PhysicalExamination.Teeth,
                Limbs = pet.PhysicalExamination.Limbs,
                Skin = pet.PhysicalExamination.Skin,
                Fur = pet.PhysicalExamination.Fur,
            }
        };

        // Then 新 GroomingRecord 的 Eyes 預設值應為 "正常"
        newRec.PhysicalExamination.Eyes.Should().Be("正常", "新建 GroomingRecord 的預設值應來自 Pet");

        await connection.CloseAsync();
        connection.Dispose();
    }
}
